import{_ as l,a0 as o,w as d,s as r,I as t,x as s,a1 as i,A as e,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"ninja：一个简单的构建方式 | LCTT x X-CMD","titleTemplate":false,"description":"ninja：一个简单的构建方式 | LCTT (202011) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"ninja：一个简单的构建方式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"ninja：一个简单的构建方式 | LCTT (202011) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202011/20201026 ninja- a simple way to do builds","title":"ninja：一个简单的构建方式","tag":"202011","desc":""},"relativePath":"202011/20201026 ninja- a simple way to do builds.md","filePath":"[post].md"}'),u={name:"202011/20201026 ninja- a simple way to do builds.md"};function f(g,n,b,h,m,k){const a=o("Link");return d(),r("div",null,[n[32]||(n[32]=t("h1",{id:"ninja-一个简单的构建方式",tabindex:"-1"},[s("ninja：一个简单的构建方式 "),t("a",{class:"header-anchor",href:"#ninja-一个简单的构建方式","aria-label":"Permalink to “ninja：一个简单的构建方式”"},"​")],-1)),t("p",null,[n[1]||(n[1]=s("大家好！每隔一段时间，我就会发现一款我非常喜欢的新软件，今天我想说说我最近喜欢的一款软件：",-1)),i(a,{href:"https://ninja-build.org/"},{default:e(()=>[...n[0]||(n[0]=[s("ninja",-1)])]),_:1}),n[2]||(n[2]=s("！",-1))]),n[33]||(n[33]=p(`<h3 id="增量构建很有用" tabindex="-1">增量构建很有用 <a class="header-anchor" href="#增量构建很有用" aria-label="Permalink to “增量构建很有用”">​</a></h3><p>我做了很多小项目，在这些项目中，我想设置增量构建。例如，现在我正在写一本关于 bash 的杂志，杂志的每一页都有一个 <code>.svg</code>文件。我需要将 SVG 转换为 PDF，我的做法是这样的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for i in *.svg</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>    svg2pdf $i $i.pdf # or \${i/.svg/.pdf} if you want to get really fancy</span></span>
<span class="line"><span>done</span></span></code></pre></div><p>这很好用，但是我的 <code>svg2pdf</code> 脚本有点慢（它使用 Inkscape），而且当我刚刚只更新了一页的时候，必须等待 90 秒或者其他什么时间来重建所有的 PDF 文件，这很烦人。</p><h3 id="构建系统是让人困惑的" tabindex="-1">构建系统是让人困惑的 <a class="header-anchor" href="#构建系统是让人困惑的" aria-label="Permalink to “构建系统是让人困惑的”">​</a></h3><p>在过去，我对使用 <code>make</code> 或 <code>bazel</code> 这样的构建系统来做我的小项目一直很反感，因为 <code>bazel</code> 是个大而复杂的东西，而 <code>make</code> 对我来说感觉有点神秘。我真的不想使用它们中的任何一个。</p><p>所以很长时间以来，我只是写了一个 bash 脚本或者其他的东西来进行构建，然后就认命了，有时候只能等一分钟。</p><h3 id="ninja-是一个极其简单的构建系统" tabindex="-1">ninja 是一个极其简单的构建系统 <a class="header-anchor" href="#ninja-是一个极其简单的构建系统" aria-label="Permalink to “ninja 是一个极其简单的构建系统”">​</a></h3><p>但 <code>ninja</code> 并不复杂！以下是我所知道的关于 ninja 构建文件的语法：创建一个 <code>rule</code> 和一个 <code>build</code>：</p><p><code>rule</code> 有一个命令（<code>command</code>）和描述（<code>description</code>）参数（描述只是给人看的，所以你可以知道它在构建你的代码时在做什么）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rule svg2pdf</span></span>
<span class="line"><span>  command = inkscape $in --export-text-to-path --export-pdf=$out</span></span>
<span class="line"><span>  description = svg2pdf $in $out</span></span></code></pre></div><p><code>build</code> 的语法是 <code>build output_file: rule_name input_files</code>。下面是一个使用 <code>svg2pdf</code> 规则的例子。输出在规则中的 <code>$out</code> 里，输入在 <code>$in</code> 里。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>build pdfs/variables.pdf: svg2pdf variables.svg</span></span></code></pre></div><p>这就完成了！如果你把这两个东西放在一个叫 <code>build.ninja</code> 的文件里，然后运行 <code>ninja</code>，ninja 会运行 <code>inkscape variables.svg --export-text-to-path --export-pdf=pdfs/variables.pdf</code>。然后如果你再次运行它，它不会运行任何东西（因为它可以告诉你已经构建了 <code>pdfs/variables.pdf</code>，而且是最新的）。</p>`,14)),t("p",null,[n[5]||(n[5]=s("Ninja 还有一些更多的功能（见",-1)),i(a,{href:"https://ninja-build.org/manual.html"},{default:e(()=>[...n[3]||(n[3]=[s("手册",-1)])]),_:1}),n[6]||(n[6]=s("），但我还没有用过。它最初是",-1)),i(a,{href:"http://neugierig.org/software/chromium/notes/2011/02/ninja.html"},{default:e(()=>[...n[4]||(n[4]=[s("为 Chromium",-1)])]),_:1}),n[7]||(n[7]=s(" 构建的，所以即使只有一个小的功能集，它也能支持大型构建。",-1))]),n[34]||(n[34]=p(`<h3 id="ninja-文件通常是自动生成的" tabindex="-1">ninja 文件通常是自动生成的 <a class="header-anchor" href="#ninja-文件通常是自动生成的" aria-label="Permalink to “ninja 文件通常是自动生成的”">​</a></h3><p>ninja 的神奇之处在于，你不必使用一些混乱的构建语言，它们很难记住，因为你不经常使用它（比如 <code>make</code>），相反，ninja 语言超级简单，如果你想做一些复杂的事情，那么你只需使用任意编程语言生成你想要的构建文件。</p><p>我喜欢写一个 <code>build.py</code> 文件，或者像这样的文件，创建 ninja 的构建文件，然后运行 <code>ninja</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>with open(&#39;build.ninja&#39;, &#39;w&#39;) as ninja_file:</span></span>
<span class="line"><span>    # write some rules</span></span>
<span class="line"><span>    ninja_file.write(&quot;&quot;&quot;</span></span>
<span class="line"><span>rule svg2pdf</span></span>
<span class="line"><span>  command = inkscape $in --export-text-to-path --export-pdf=$out</span></span>
<span class="line"><span>  description = svg2pdf $in $out</span></span>
<span class="line"><span>&quot;&quot;&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # some for loop with every file I need to build</span></span>
<span class="line"><span>    for filename in things_to_convert:</span></span>
<span class="line"><span>        ninja_file.write(f&quot;&quot;&quot;</span></span>
<span class="line"><span>build {filename.replace(&#39;svg&#39;, &#39;pdf&#39;)}: svg2pdf {filename}</span></span>
<span class="line"><span>&quot;&quot;&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># run ninja</span></span>
<span class="line"><span>import subprocess</span></span>
<span class="line"><span>subprocess.check_call([&#39;ninja&#39;])</span></span></code></pre></div><p>我相信有一堆 <code>ninja</code> 的最佳实践，但我不知道。对于我的小项目而言，我发现它很好用。</p><h3 id="meson-是一个生成-ninja-文件的构建系统" tabindex="-1">meson 是一个生成 ninja 文件的构建系统 <a class="header-anchor" href="#meson-是一个生成-ninja-文件的构建系统" aria-label="Permalink to “meson 是一个生成 ninja 文件的构建系统”">​</a></h3>`,6)),t("p",null,[n[10]||(n[10]=s("我对 ",-1)),i(a,{href:"https://mesonbuild.com/Tutorial.html"},{default:e(()=>[...n[8]||(n[8]=[s("Meson",-1)])]),_:1}),n[11]||(n[11]=s(" 还不太了解，但最近我在构建一个 C 程序 （",-1)),i(a,{href:"https://blog.sesse.net/blog/tech/2020-09-28-00-37_introducing_plocate"},{default:e(()=>[...n[9]||(n[9]=[s("plocate",-1)])]),_:1}),n[12]||(n[12]=s("，一个比 ",-1)),n[13]||(n[13]=t("code",null,"locate",-1)),n[14]||(n[14]=s(" 更快的替代方案）时，我注意到它有不同的构建说明，而不是通常的 ",-1)),n[15]||(n[15]=t("code",null,"./configure; make; make install",-1)),n[16]||(n[16]=s("：",-1))]),n[35]||(n[35]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>meson builddir</span></span>
<span class="line"><span>cd builddir</span></span>
<span class="line"><span>ninja</span></span></code></pre></div><p>看起来 Meson 是一个可以用 ninja 作为后端的 C/C++/Java/Rust/Fortran 构建系统。</p><h3 id="就是这些" tabindex="-1">就是这些！ <a class="header-anchor" href="#就是这些" aria-label="Permalink to “就是这些！”">​</a></h3><p>我使用 ninja 已经有几个月了。我真的很喜欢它，而且它几乎没有给我带来让人头疼的构建问题，这让我感觉非常神奇。</p><hr>`,5)),t("p",null,[n[18]||(n[18]=s("via: ",-1)),i(a,{href:"https://jvns.ca/blog/2020/10/26/ninja--a-simple-way-to-do-builds/"},{default:e(()=>[...n[17]||(n[17]=[s("https://jvns.ca/blog/2020/10/26/ninja--a-simple-way-to-do-builds/",-1)])]),_:1})]),t("p",null,[n[23]||(n[23]=s("作者：",-1)),i(a,{href:"https://jvns.ca/"},{default:e(()=>[...n[19]||(n[19]=[s("Julia Evans",-1)])]),_:1}),n[24]||(n[24]=s(" 选题：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...n[20]||(n[20]=[s("lujun9972",-1)])]),_:1}),n[25]||(n[25]=s(" 译者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:e(()=>[...n[21]||(n[21]=[s("geekpi",-1)])]),_:1}),n[26]||(n[26]=s(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:e(()=>[...n[22]||(n[22]=[s("wxy",-1)])]),_:1})]),t("p",null,[n[29]||(n[29]=s("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...n[27]||(n[27]=[s("LCTT",-1)])]),_:1}),n[30]||(n[30]=s(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:e(()=>[...n[28]||(n[28]=[s("Linux中国",-1)])]),_:1}),n[31]||(n[31]=s(" 荣誉推出",-1))])])}const T=l(u,[["render",f]]);export{v as __pageData,T as default};
